if(type==='autoSell'){if(!G.canDelegate(s))return 'Salgsapparatet krever Pusher-rang og én driftsleder.';s.autoSell=!s.autoSell;msg=s.autoSell?'Salgsapparatet selger hele lageret automatisk ved hvert ukesoppgjør. Ingen fast omsetningsgrense.':'Det automatiske salgsapparatet er pauset.';}
else if(type==='waitDay'){const before=s.cash;G.elapse(s,1);s.heat=clamp(s.heat-2);s.crew.fatigue=clamp(s.crew.fatigue-2);s.summary={weeks:1/7,days:1,net:s.cash-before,stop:'En rolig dag. −2 søkelys og −2 slitasje, i tillegg til eventuell ukedrift.'};msg='Du tok en rolig dag. −2 søkelys, −2 slitasje.';}
else if(['week','rest','shift'].includes(type)){const before=s.cash,start=s.day;G.elapse(s,7,type==='rest'?'rest':type==='shift'?'shift':'week');s.summary={weeks:(s.day-start)/7,days:s.day-start,net:s.cash-before,stop:s.event?'En avgjørelse venter.':'Perioden er gjort opp.'};msg='Perioden er gjort opp.';}
